import Foundation
import XCTest
import AgentRuntimeKit
import AgentTranscriptProjection
import AgentTranscriptAssembly
import AgentTranscriptPersistence

final class ProjectionTests:XCTestCase {
    func testEmptyProjectionAndCounts() {let s=projectionService();XCTAssertEqual(s.build(from:.empty),.empty);XCTAssertEqual(s.projectionCounts(for:AgentTranscript.empty),.zero);XCTAssertEqual(s.estimatedWorkingUnitCount(for:.empty),0)}
    func testRequestAndConclusionSpineHasStableAnchors() {
        let t=projectionTurn(),p=projectionService().build(from:.init(turns:[t]));XCTAssertEqual(p.workingBlocks.map(\.kind),[.request,.conclusion]);XCTAssertEqual(p.rowAnchorIndex[t.request!.id],.request(turnID:t.id));XCTAssertEqual(p.rowAnchorIndex[t.conclusionActivityID!],.conclusion(turnID:t.id,activityID:t.conclusionActivityID!));XCTAssertEqual(Set(p.anchorBlockIndex.values),Set(p.workingBlocks.map(\.id)))
    }
    func testEquivalentBuildsAndBlockIdentifiersAreStable() {let t=AgentTranscript(turns:[projectionTurn(tools:12,narration:true)]),s=projectionService();XCTAssertEqual(s.build(from:t),s.build(from:t));XCTAssertEqual(s.blocks(for:t),s.blocks(for:t))}
    func testSmallToolCallResultPairsBecomeOneBlockPerExecution() {let t=projectionTurn(tools:3),p=projectionService().build(from:.init(turns:[t]));let tools=p.workingBlocks.filter{$0.kind == .standaloneTool};XCTAssertEqual(tools.count,3);XCTAssertEqual(tools.map{$0.rows.count},[2,2,2]);XCTAssertEqual(projectionService().standaloneToolBlockCount(for:t),3)}
    func testGroupedHistoryCollapsesOlderToolsAndUsesHostSections() {let t=projectionTurn(tools:12,narration:true),p=projectionService().build(from:.init(turns:[t]));let group=p.workingBlocks.first{$0.kind == .groupedHistory};XCTAssertNotNil(group);XCTAssertTrue(group!.groupedHistory!.sections.allSatisfy{$0.title == "section"});XCTAssertEqual(p.workingBlocks.last?.kind,.conclusion)}
    func testHiddenActivityIdsAreRetainedInGroupedBlockAnchors() {let t=projectionTurn(tools:12),p=projectionService().build(from:.init(turns:[t])),group=p.workingBlocks.first{$0.kind == .groupedHistory}!;XCTAssertFalse(group.activityIDs.isEmpty);XCTAssertTrue(group.activityIDs.allSatisfy{p.rowAnchorIndex[$0] != nil})}
    func testGroupedToolResultsAreExcludedFromVisibleToolResultUniverse() {let t=projectionTurn(tools:12),p=projectionService().build(from:.init(turns:[t])),s=projectionService();let visible=s.visibleToolResultRowIDs(in:p);XCTAssertEqual(visible,Set(p.workingBlocks.flatMap(\.rows).filter{$0.kind == .toolResult}.map(\.id)));XCTAssertLessThan(visible.count,12)}
    func testNewestFirstDetailedToolAllocationStaysWithinGlobalBudget() {let a=projectionTurn(tools:6),b=projectionTurn(1,tools:6),limits=projectionService().detailedToolTailLimits(for:.init(turns:[a,b]));XCTAssertEqual(limits[b.id],6);XCTAssertEqual(limits[a.id],2);XCTAssertEqual(limits.values.reduce(0,+),8)}
    func testNonFullTurnsReceiveNoDetailedTailAllocation() {let turns=[projectionTurn(tier:.summary),projectionTurn(1,tier:.archived),projectionTurn(2,tier:.condensed)];XCTAssertEqual(projectionService().detailedToolTailLimits(for:.init(turns:turns)),Dictionary(uniqueKeysWithValues:turns.map{($0.id,0)}))}
    func testFrozenLimitClampsNegativeAndRequiresCollapse() {var t=projectionTurn(tools:12);t.frozenDetailedToolTailLimit = -2;XCTAssertEqual(projectionService().normalizedFrozenDetailedToolTailLimit(for:t),0);t.frozenDetailedToolTailLimit=100;XCTAssertNil(projectionService().normalizedFrozenDetailedToolTailLimit(for:t))}
    func testActiveOrNonFullFrozenLimitIsIgnored() {var t=projectionTurn(tools:12,completed:false);t.frozenDetailedToolTailLimit=0;XCTAssertNil(projectionService().normalizedFrozenDetailedToolTailLimit(for:t));t.retentionTier = .summary;XCTAssertNil(projectionService().normalizedFrozenDetailedToolTailLimit(for:t))}
    func testRefreshingCompletedTurnFreezesDetailedTailAndCachesCollapsedSummary() {let t=projectionTurn(tools:12),result=projectionService().refreshCompletedFullTurnGroupedHistoryCaches(in:.init(turns:[t]));XCTAssertNotNil(result.turns[0].frozenDetailedToolTailLimit);XCTAssertNotNil(result.turns[0].responseSpans[0].fullRenderGroupedHistoryCache);XCTAssertEqual(projectionService().refreshCompletedFullTurnGroupedHistoryCaches(in:result),result)}
    func testRefreshClearsCachesOnIneligibleTurn() {var t=projectionService().refreshCompletedFullTurnGroupedHistoryCaches(in:.init(turns:[projectionTurn(tools:12)])).turns[0];t.responseSpans[0].lifecycle = .open;let result=projectionService().refreshCompletedFullTurnGroupedHistoryCaches(in:.init(turns:[t]));XCTAssertNil(result.turns[0].responseSpans[0].fullRenderGroupedHistoryCache)}
    func testCompletedTurnCacheHitsAreObservedAndActiveTurnHasNoCache() {var metrics:[AgentTranscriptProjectionBuildMetrics]=[];var p=projectionPorts();p.diagnosticsEnabled={true};p.observeBuild={metrics.append($0)};let s=AgentTranscriptProjectionService(services:p),t=AgentTranscript(turns:[projectionTurn(tools:2),projectionTurn(1,tools:1,completed:false)]),first=s.buildWithCaches(from:t,turnCaches:[:]),second=s.buildWithCaches(from:t,turnCaches:first.updatedTurnCaches);XCTAssertEqual(first.projection,second.projection);XCTAssertEqual(first.updatedTurnCaches.count,1);XCTAssertEqual(metrics.last?.cacheHitCount,1)}
    func testProtectedCompletedTurnDoesNotUseCache() {var metrics:[AgentTranscriptProjectionBuildMetrics]=[];var p=projectionPorts();p.diagnosticsEnabled={true};p.observeBuild={metrics.append($0)};let s=AgentTranscriptProjectionService(services:p),t=AgentTranscript(turns:[projectionTurn(tools:2)]),cache=s.buildWithCaches(from:t,turnCaches:[:]);_ = s.buildWithCaches(from:t,protection:.protectedTurn(t.turns[0].id),turnCaches:cache.updatedTurnCaches);XCTAssertEqual(metrics.last?.cacheHitCount,0)}
    func testDeletedTurnCachesAreRemoved() {let s=projectionService(),t=AgentTranscript(turns:[projectionTurn(),projectionTurn(1)]),cache=s.buildWithCaches(from:t,turnCaches:[:]);XCTAssertEqual(s.buildWithCaches(from:.init(turns:[t.turns[1]]),turnCaches:cache.updatedTurnCaches).updatedTurnCaches.count,1)}
    func testValidationTokenPinsStructuralFieldsAndRetainsLegacyCoarseContentRule() {let s=projectionService();var t=projectionTurn(tools:1);let token=s.validationToken(for:t);t.responseSpans[0].activities[0].text="changed";XCTAssertEqual(token,s.validationToken(for:t));t.frozenDetailedToolTailLimit=1;XCTAssertNotEqual(token,s.validationToken(for:t))}
    func testUpdatedCachesRetainOnlyCompletedAndUnprotectedTurns() {let s=projectionService(),a=projectionTurn(),b=projectionTurn(1,completed:false),t=AgentTranscript(turns:[a,b]),p=s.build(from:t);XCTAssertEqual(s.updatedTurnCaches(for:t,projection:p).count,1);XCTAssertTrue(s.updatedTurnCaches(for:t,projection:p,protection:.protectedTurn(a.id)).isEmpty)}
    func testFrozenPrefixReuseMatchesFullBuild() {let s=projectionService(),a=projectionTurn(tier:.summary),b=projectionTurn(1),previous=AgentTranscript(turns:[a]),frontier=AgentTranscriptCompactionFrontier(frozenPrefixTurnCount:1,lastFrozenTurnID:a.id),current=AgentTranscript(turns:[a,b],compactionFrontier:frontier);let reused=s.buildReusingFrozenPrefix(from:current,previousTranscript:previous,previousProjection:s.build(from:previous),previousProtection:.none,reusableFrozenPrefixTurnCount:1);XCTAssertEqual(reused,s.build(from:current))}
    func testFrozenPrefixRejectsChangedProtectionMissingFrontierOrPrefixMutation() {let s=projectionService(),a=projectionTurn(tier:.summary),b=projectionTurn(1),previous=AgentTranscript(turns:[a]),projection=s.build(from:previous);var current=AgentTranscript(turns:[a,b]);XCTAssertNil(s.buildReusingFrozenPrefix(from:current,previousTranscript:previous,previousProjection:projection,previousProtection:.none,reusableFrozenPrefixTurnCount:1));current.compactionFrontier = .init(frozenPrefixTurnCount:1,lastFrozenTurnID:a.id);XCTAssertNil(s.buildReusingFrozenPrefix(from:current,previousTranscript:previous,previousProjection:projection,previousProtection:.protectedTurn(a.id),reusableFrozenPrefixTurnCount:1));current.turns[0].lastActivityAt=Date(timeIntervalSince1970:999);XCTAssertNil(s.buildReusingFrozenPrefix(from:current,previousTranscript:previous,previousProjection:projection,previousProtection:.none,reusableFrozenPrefixTurnCount:1))}
    func testArchiveAndWorkingProjectionFilterTheirAnchorUniverses() {let s=projectionService(),a=projectionTurn(tier:.archived),b=projectionTurn(1),p=s.build(from:.init(turns:[a,b])),archive=s.archivedProjection(from:p),working=s.workingProjection(from:p);XCTAssertTrue(archive.blocks.allSatisfy{$0.isArchived});XCTAssertTrue(working.archivedBlocks.isEmpty);XCTAssertEqual(Set(archive.rowAnchorIndex.keys),Set(archive.rows.map(\.id)));XCTAssertEqual(Set(working.rowAnchorIndex.keys),Set(working.workingRows.map(\.id)))}
    func testProjectionCountsMatchMaterializedBlocksAcrossAllRetentionTiers() {let s=projectionService();for tier in AgentTranscriptRetentionTier.allCases {let t=AgentTranscript(turns:[projectionTurn(tools:12,tier:tier)]),p=s.build(from:t);XCTAssertEqual(s.projectionCounts(for:t),s.projectionCounts(for:p));XCTAssertEqual(s.estimatedWorkingUnitCount(for:t),p.workingUnitCount)}}
    func testRowsAndBlocksHonorArchivedTier() {let s=projectionService(),t=projectionTurn(tier:.archived);XCTAssertEqual(s.rows(for:t,archived:true),s.blocks(for:t,archived:true).flatMap(\.rows));XCTAssertFalse(s.blocks(for:.init(turns:[t])).isEmpty)}
    func testArchivedRowsUseStableSummaryAndConclusionIdentities() {var t=projectionTurn(tier:.archived);t.conclusionActivityID=nil;t.responseSpans=[];let p=projectionService().build(from:.init(turns:[t]));XCTAssertTrue(p.archivedRows.contains{$0.id == t.summary!.middleSummaryItemID});XCTAssertTrue(p.archivedRows.contains{$0.id == AgentTranscriptIdentity.conclusionID(for:t.id)})}
    func testDisplaylessAssistantAndSuppressedToolsDoNotBecomeVisibleRows() {var t=projectionTurn(tools:1,name:"hidden");let empty=projectionRow(200,kind:.assistant,text:" \n");t.responseSpans[0].activities.append(.init(from:empty));let rows=projectionService().build(from:.init(turns:[t])).workingRows;XCTAssertFalse(rows.contains{$0.id==empty.id || $0.toolName == "hidden"})}
    func testToolProcessorFactoryIsPerOperationNotGlobal() {var count=0;var p=projectionPorts();let base=p.makeToolProcessor;p.makeToolProcessor={count+=1;return base()};let s=AgentTranscriptProjectionService(services:p),t=AgentTranscript(turns:[projectionTurn(tools:12)]);_ = s.build(from:t);_ = s.build(from:t);XCTAssertEqual(count,2)}
    func testSummaryAggregationGroupsExecutionPairsAndUsesLatestStatus() {let t=projectionTurn(tools:12),p=projectionService().build(from:.init(turns:[t])),summary=p.workingBlocks.first{$0.kind == .groupedHistory}!.groupedHistory!.summary.toolSummary!;XCTAssertEqual(summary.toolNameCounts["read"],summary.toolCount);XCTAssertFalse(summary.containsRunningWork);XCTAssertFalse(summary.containsFailure)}
    func testHostGroupedSummarySanitizerReceivesFrozenPresentation() {var called=0;var ports=projectionPorts();ports.sanitizeGroupedSummary={s in called+=1;return s};let service=AgentTranscriptProjectionService(services:ports),t=service.refreshCompletedFullTurnGroupedHistoryCaches(in:.init(turns:[projectionTurn(tools:12)]));_ = service.build(from:t);XCTAssertGreaterThan(called,0)}
    func testExplicitClockAndDiagnosticsPreserveDurationAndCounts() {var ticks=0,metrics:[AgentTranscriptProjectionBuildMetrics]=[];var ports=projectionPorts();ports.clock={ticks+=1;return Double(ticks)};ports.diagnosticsEnabled={true};ports.observeBuild={metrics.append($0)};_ = AgentTranscriptProjectionService(services:ports).build(from:.init(turns:[projectionTurn()]));XCTAssertEqual(metrics[0].durationMS,1000);XCTAssertEqual(metrics[0].turnCount,1)}
    func testEveryAnchorCarriesItsTurnIdentity() {let id=UUID(),span=UUID(),row=UUID();for anchor in [AgentTranscriptAnchor.request(turnID:id),.summary(turnID:id),.groupedHistory(turnID:id,spanID:span),.activity(turnID:id,spanID:span,activityID:row),.conclusion(turnID:id,activityID:row)]{XCTAssertEqual(anchor.turnID,id)}}
    func execution(_ id:String="preferred",status:AgentTranscriptToolStatus = .success)->AgentTranscriptToolExecution {
        .init(stableExecutionID:id,toolName:nil,invocationID:nil,argsJSON:nil,resultJSON:nil,toolIsError:nil,status:status)
    }
    func testMetadataMergeFillsNilFieldsWithoutChangingPreferredIdentityOrStatus() {
        let preferred=execution();var fallback=execution("fallback",status:.failed);fallback.toolName="read";fallback.invocationID=UUID();fallback.argsJSON="args";fallback.resultJSON="result";fallback.toolIsError=true;fallback.processID="pid";fallback.exitCode=4;fallback.summaryText="summary"
        let result=AgentTranscriptExecutionMetadata.merged(preferred,with:fallback)
        XCTAssertEqual(result.stableExecutionID,"preferred");XCTAssertEqual(result.status,.success);XCTAssertEqual(result.toolName,fallback.toolName);XCTAssertEqual(result.invocationID,fallback.invocationID);XCTAssertEqual(result.argsJSON,"args");XCTAssertEqual(result.resultJSON,"result");XCTAssertEqual(result.toolIsError,true);XCTAssertEqual(result.processID,"pid");XCTAssertEqual(result.exitCode,4);XCTAssertEqual(result.summaryText,"summary")
    }
    func testMetadataMergeKeepsEmptyArgumentAndFalseErrorButReplacesEmptySummary() {
        var preferred=execution();preferred.argsJSON="";preferred.toolIsError=false;preferred.summaryText="";var fallback=execution();fallback.argsJSON="fallback";fallback.toolIsError=true;fallback.summaryText="fallback"
        let result=AgentTranscriptExecutionMetadata.merged(preferred,with:fallback);XCTAssertEqual(result.argsJSON,"");XCTAssertEqual(result.toolIsError,false);XCTAssertEqual(result.summaryText,"fallback")
    }
    func testMetadataMergePreservesFallbackFirstPathOrderAndSummaryOnlyUnion() {
        var preferred=execution();preferred.keyPaths=["new","shared"];var fallback=execution();fallback.keyPaths=["shared","old"];fallback.summaryOnly=true
        let result=AgentTranscriptExecutionMetadata.merged(preferred,with:fallback);XCTAssertEqual(result.keyPaths,["shared","old","new"]);XCTAssertTrue(result.summaryOnly)
    }
    func testNonemptyPreferredMetadataIsNeverOverwritten() {
        var preferred=execution();preferred.toolName="original";preferred.resultJSON="original";preferred.summaryText="original";var fallback=execution();fallback.toolName="new";fallback.resultJSON="new";fallback.summaryText="new"
        XCTAssertEqual(AgentTranscriptExecutionMetadata.merged(preferred,with:fallback),preferred)
    }
    func testFrozenReuseRejectsZeroCountAndTranscriptWithoutSuffix() {
        let s=projectionService(),a=projectionTurn(tier:.summary),t=AgentTranscript(turns:[a],compactionFrontier:.init(frozenPrefixTurnCount:1,lastFrozenTurnID:a.id)),p=s.build(from:t)
        for count in [0,1] {XCTAssertNil(s.buildReusingFrozenPrefix(from:t,previousTranscript:t,previousProjection:p,previousProtection:.none,reusableFrozenPrefixTurnCount:count))}
    }
    func testCompletedFrozenLimitNeverWidensWhenNewTurnAppears() {
        let s=projectionService();var first=s.refreshCompletedFullTurnGroupedHistoryCaches(in:.init(turns:[projectionTurn(tools:12)]));let before=first.turns[0].frozenDetailedToolTailLimit!;first.turns.append(projectionTurn(1,tools:3))
        let result=s.refreshCompletedFullTurnGroupedHistoryCaches(in:first);XCTAssertLessThanOrEqual(result.turns[0].frozenDetailedToolTailLimit!,before)
    }
    func testCacheRefreshRecomputesWhenDetailedLimitChanges() {
        let s=projectionService();var t=s.refreshCompletedFullTurnGroupedHistoryCaches(in:.init(turns:[projectionTurn(tools:12)]));let old=t.turns[0].responseSpans[0].fullRenderGroupedHistoryCache!;t.turns[0].frozenDetailedToolTailLimit=0
        let refreshed=s.refreshCompletedFullTurnGroupedHistoryCaches(in:t);XCTAssertNotEqual(refreshed.turns[0].responseSpans[0].fullRenderGroupedHistoryCache?.collapseDigest,old.collapseDigest);XCTAssertEqual(refreshed.turns[0].responseSpans[0].fullRenderGroupedHistoryCache?.detailedToolTailLimit,0)
    }
    func testAnchorAndPresentationClosedVocabulariesRemainStable() {
        XCTAssertEqual([AgentTranscriptRenderBlockKind.request,.activityCluster,.groupedHistory,.standaloneAssistant,.standaloneTool,.standaloneNote,.middleSummary,.conclusion].map(\.rawValue),["request","activityCluster","groupedHistory","standaloneAssistant","standaloneTool","standaloneNote","middleSummary","conclusion"])
        XCTAssertEqual([AgentTranscriptBlockPresentation.expanded,.collapsed].map(\.rawValue),["expanded","collapsed"])
    }
    func testArchivedCountInitializerClampsOnlyItsCountFields() {
        let archive=AgentArchivedTranscriptProjection(blocks:[],rows:[],rowAnchorIndex:[:],anchorBlockIndex:[:],presentedRowCount:-3,blockCount:-2);XCTAssertEqual(archive.presentedRowCount,0);XCTAssertEqual(archive.blockCount,0)
    }
    func testBackwardClockDoesNotProduceNegativeDiagnosticDuration() {
        var count=0,metrics:[AgentTranscriptProjectionBuildMetrics]=[];var p=projectionPorts();p.clock={count+=1;return count==1 ? 10:5};p.diagnosticsEnabled={true};p.observeBuild={metrics.append($0)};_ = AgentTranscriptProjectionService(services:p).build(from:.empty);XCTAssertEqual(metrics[0].durationMS,0)
    }

}
